contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        require(true);
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (c.owner() == address(this)) {
            // As owner, the call may succeed or fail only due to recipient refusal;
            // if it succeeded, c's balance must be zero.
            if (!reverted) {
                assert(address(c).balance == 0);
            } else {
                assert(true);
            }
        } else {
            // A non-owner caller must never be able to withdraw.
            assert(reverted);
            assert(address(c).balance == 0);
        }
    }
    receive() external payable {}
}

